package com.casystem.onboarding.config;
import com.casystem.onboarding.model.User;import com.casystem.onboarding.repository.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component public class AdminInitializer implements CommandLineRunner{private final UserRepository users;private final PasswordEncoder enc;private final String email,pass;public AdminInitializer(UserRepository u,PasswordEncoder e,@Value("${app.admin-email}")String m,@Value("${app.admin-password}")String p){users=u;enc=e;email=m.trim().toLowerCase();pass=p;}public void run(String...a){User u=users.findByEmailAndDeletedFalse(email).orElseGet(User::new);u.setEmail(email);u.setName("Administrador");u.setRole("ADMIN");u.setDeleted(false);/* En entorno de examen la clave inicial se controla por variable de entorno. */if(u.getId()==null||!enc.matches(pass,u.getPassword()==null?"":u.getPassword()))u.setPassword(enc.encode(pass));users.save(u);}}
